import { addClass, removeClass } from "../../../core/dom/index.js";
const createProgressLazy = async (config) => {
    const { default: createProgress } = await import("../../progress/progress.js");
    return createProgress(config);
};
export const withProgress = (config) => (component) => {
    if (!config.progress) {
        return component;
    }
    let progressEventHandlers = {};
    const progressConfig = typeof config.progress === "boolean"
        ? { variant: "circular", size: 20, thickness: 2, indeterminate: true }
        : (() => {
            const { on, ...restConfig } = config.progress;
            if (on) {
                progressEventHandlers = on;
            }
            return {
                variant: "circular",
                size: 20,
                thickness: 2,
                indeterminate: true,
                ...restConfig,
            };
        })();
    let progress = null;
    let progressPromise = null;
    let isLoading = false;
    let originalText = "";
    const ensureProgress = async () => {
        if (progress)
            return progress;
        if (!progressPromise) {
            progressPromise = createProgressLazy(progressConfig).then((p) => {
                progress = p;
                addClass(progress.element, component.getClass("button__progress"));
                progress.element.style.display = "none";
                for (const event of Object.keys(progressEventHandlers)) {
                    const handler = progressEventHandlers[event];
                    if (handler)
                        p.on(event, handler);
                }
                component.progress = progress;
                return progress;
            });
        }
        return progressPromise;
    };
    const getProgressInsertionPoint = () => {
        const iconElement = component.element.querySelector(`.${component.getClass("button__icon")}`);
        if (iconElement && iconElement.nextSibling) {
            return iconElement.nextSibling;
        }
        return component.element.firstChild;
    };
    const showProgress = async () => {
        const p = await ensureProgress();
        if (p.element) {
            if (!component.element.contains(p.element)) {
                const insertPoint = getProgressInsertionPoint();
                if (insertPoint) {
                    component.element.insertBefore(p.element, insertPoint);
                }
                else {
                    component.element.appendChild(p.element);
                }
            }
            p.element.style.display = "";
            addClass(component.element, `${component.getClass("button")}--progress`);
            const iconElement = component.element.querySelector(`.${component.getClass("button__icon")}`);
            if (iconElement instanceof HTMLElement) {
                iconElement.style.display = "none";
            }
        }
        return component;
    };
    component.showProgress = showProgress;
    component.showProgressSync = () => {
        void showProgress();
        return component;
    };
    const hideProgress = async () => {
        if (!progress)
            return component;
        progress.element.style.display = "none";
        removeClass(component.element, `${component.getClass("button")}--progress`);
        const iconElement = component.element.querySelector(`.${component.getClass("button__icon")}`);
        if (iconElement instanceof HTMLElement) {
            iconElement.style.display = "";
        }
        return component;
    };
    component.hideProgress = hideProgress;
    component.hideProgressSync = () => {
        void hideProgress();
        return component;
    };
    const setProgress = async (value) => {
        const p = await ensureProgress();
        p.setValue(value);
        return component;
    };
    component.setProgress = setProgress;
    component.setProgressSync = (value) => {
        void setProgress(value);
        return component;
    };
    const setIndeterminate = async (indeterminate) => {
        const p = await ensureProgress();
        p.setIndeterminate(indeterminate);
        return component;
    };
    component.setIndeterminate = setIndeterminate;
    component.setIndeterminateSync = (indeterminate) => {
        void setIndeterminate(indeterminate);
        return component;
    };
    const readLabel = () => component.text ? component.text.getText() : component.getText?.();
    const writeLabel = (value) => {
        if (component.text)
            component.text.setText(value);
        else
            component.setText?.(value);
    };
    const setLoading = async (loading, text) => {
        if (loading && !isLoading) {
            originalText = readLabel() ?? "";
            isLoading = true;
            component.element.setAttribute("aria-busy", "true");
            await showProgress();
            if (component.disabled?.disable) {
                component.disabled.disable();
            }
            if (text)
                writeLabel(text);
        }
        else if (!loading && isLoading) {
            isLoading = false;
            component.element.removeAttribute("aria-busy");
            await hideProgress();
            if (component.disabled?.enable) {
                component.disabled.enable();
            }
            if (text)
                writeLabel(text);
            else if (originalText)
                writeLabel(originalText);
        }
        return component;
    };
    component.setLoading = setLoading;
    component.setLoadingSync = (loading, text) => {
        void setLoading(loading, text);
        return component;
    };
    if (component.lifecycle) {
        const originalDestroy = component.lifecycle.destroy;
        component.lifecycle.destroy = () => {
            if (progress) {
                progress.destroy();
            }
            if (progress && progress.element.parentNode) {
                progress.element.parentNode.removeChild(progress.element);
            }
            originalDestroy();
        };
    }
    if (config.showProgress) {
        void ensureProgress().then(() => showProgress());
    }
    return component;
};
